using Astronomy.MediaFactory.Core.KnowledgeFoundation;using Astronomy.MediaFactory.Core.KnowledgeFoundation.Catalog;using Astronomy.MediaFactory.Core.KnowledgeFoundation.Query;using Astronomy.MediaFactory.Core.KnowledgeFoundation.Query.Execution;using Astronomy.MediaFactory.Core.KnowledgeFoundation.TypedDomains;
namespace Astronomy.MediaFactory.Tests.KnowledgeFoundation.Integration;
public sealed class AstronomyKnowledgeFoundationEndToEndTests{[Fact]public void Catalog_query_flow_returns_exact_entry_and_fingerprint(){var f=new KnowledgeFoundationIntegrationFixture();var entry=f.Catalog.Snapshot.KnowledgeTypes.First();var q=new AstronomyKnowledgeCatalogQuery(entryIds:[entry.Id],page:new(0,10));var r=f.CatalogEngine.Execute(q);Assert.Equal(AstronomyKnowledgeQueryExecutionStatus.Succeeded,r.Status);Assert.Equal(q.Fingerprint,r.Metadata.Fingerprint);Assert.Equal(entry.Id,r.Items.Single().Id);Assert.Equal(f.Catalog.Snapshot.Entries.Count,r.Metadata.SourceCount);Assert.Equal(1,r.Metadata.MatchedCount);Assert.Equal(1,r.Metadata.ReturnedCount);}[Fact]public void Statement_query_flow_filters_orders_pages_and_does_not_mutate_source(){var f=new KnowledgeFoundationIntegrationFixture();var source=new List<IAstronomyKnowledgeStatement>{f.Statement("s3",3,"mars",KnowledgeFoundationStatus.Approved),f.Statement("s1",1,"mars",KnowledgeFoundationStatus.Approved),f.Statement("s2",2,"venus",KnowledgeFoundationStatus.Reviewed),f.Statement("s4",4,"mars",KnowledgeFoundationStatus.Draft)};var q=new AstronomyKnowledgeStatementQuery(subjects:new([new AstronomyEntityReference("mars")]),statuses:new([KnowledgeFoundationStatus.Approved]),version:new(minimumRevision:new KnowledgeVersion(1)),ordering:[new(AstronomyKnowledgeStatementSortField.Revision,AstronomyKnowledgeQuerySortDirection.Descending)],page:new(0,1));var r=f.StatementEngine.Execute(q,source);Assert.Equal(AstronomyKnowledgeQueryExecutionStatus.Succeeded,r.Status);Assert.Equal(new[]{"s3"},r.Items.Select(x=>x.Id.Value));Assert.Equal(4,r.Metadata.SourceCount);Assert.Equal(2,r.Metadata.MatchedCount);Assert.Equal(1,r.Metadata.ReturnedCount);Assert.Equal(new[]{"s3","s1","s2","s4"},source.Select(x=>x.Id.Value));}[Fact]public void Rejected_catalog_query_returns_exact_issue_and_no_items(){var f=new KnowledgeFoundationIntegrationFixture();var q=new AstronomyKnowledgeCatalogQuery(knowledgeTypes:new([AstronomyKnowledgeTypeId.Create("unknown.type")]));var r=f.CatalogEngine.Execute(q);Assert.Equal(AstronomyKnowledgeQueryExecutionStatus.Rejected,r.Status);Assert.Empty(r.Items);Assert.Equal(AstronomyKnowledgeQueryValidationCode.UnknownKnowledgeType,r.ValidationIssues.Single().Code);Assert.Equal("$.knowledgeTypes",r.ValidationIssues.Single().Path);}}
